using UnityEngine;using UnityEngine.UI;
namespace LostRealmsOW {
 public sealed partial class OpenWorldMobileHud {
  GameObject horsePanel;Text horseHint;Button leftHorse,rightHorse;Button[] stableBuy;Text staminaHorse;
  internal void UpdateHorseProgression(){if(!safeRoot)return;var p=OpenWorldHorseProgression.Instance;var gm=OpenWorldManager.I?OpenWorldManager.I:UnityEngine.Object.FindAnyObjectByType<OpenWorldManager>();if(!p||!gm||!gm.Hero)return;
   if(!horsePanel){var r=Rect("Horse progression",safeRoot,new Vector2(.5f,0),new Vector2(.5f,0),new Vector2(0,260),new Vector2(620,225));horsePanel=r.gameObject;var fill=Rect("Horse panel backing",r,Vector2.zero,Vector2.one,Vector2.zero,Vector2.zero);fill.offsetMin=new Vector2(3,3);fill.offsetMax=new Vector2(-3,-3);fill.gameObject.AddComponent<Image>().color=new Color(.025f,.045f,.065f,.98f);fill.SetAsFirstSibling();theme.Round(horsePanel,new Color(.04f,.07f,.10f,.98f),18,true);horseHint=Label(r,"",new Vector2(0,65),new Vector2(590,80),Vector2.one*.5f,20);leftHorse=PillButton(r,"BALANCE LEFT",new Vector2(-140,-55),new Vector2(240,64),Vector2.one*.5f,20);rightHorse=PillButton(r,"BALANCE RIGHT",new Vector2(140,-55),new Vector2(240,64),Vector2.one*.5f,20);leftHorse.onClick.AddListener(()=>OpenWorldHorseProgression.Instance.Counter(-1));rightHorse.onClick.AddListener(()=>OpenWorldHorseProgression.Instance.Counter(1));stableBuy=new Button[3];for(int i=0;i<3;i++){int id=i;stableBuy[i]=PillButton(r,OpenWorldHorseProgression.Breeds[i].Name+"\n"+OpenWorldHorseProgression.Breeds[i].Price+" GOLD",new Vector2(-200+i*200,-55),new Vector2(190,70),Vector2.one*.5f,16);stableBuy[i].onClick.AddListener(()=>OpenWorldHorseProgression.Instance.Buy(id));}staminaHorse=Label(safeRoot,"",new Vector2(0,105),new Vector2(430,30),new Vector2(.5f,0),17);}
   bool allowed=!gm.Hero.Dead&&!gm.IsModalOpen&&(!titleRoot||!titleRoot.activeSelf);bool taming=p.Target;bool stable=allowed&&!gm.Hero.IsMounted&&Vector2.Distance(new Vector2(gm.Hero.transform.position.x,gm.Hero.transform.position.z),new Vector2(-36,8))<9;
   horsePanel.SetActive(allowed&&(taming||stable));leftHorse.gameObject.SetActive(taming);rightHorse.gameObject.SetActive(taming);for(int i=0;i<3;i++){stableBuy[i].gameObject.SetActive(!taming);stableBuy[i].GetComponentInChildren<Text>().text=OpenWorldHorseProgression.Breeds[i].Name+"\n"+(gm.CollectedWorldIds.Contains("horse-owned:"+i)?"SELECT":OpenWorldHorseProgression.Breeds[i].Price+" GOLD");}
   if(taming)horseHint.text="TAMING • "+OpenWorldHorseProgression.Breeds[p.Target.Breed].Name+"\nCounter "+(p.Direction<0?"LEFT":"RIGHT")+" in "+Mathf.Max(0,p.Deadline-Time.unscaledTime).ToString("F1")+"s • "+p.Successes+"/"+p.Required+" • Mistakes "+p.Mistakes+"/3";
   else horseHint.text="VERDANT STABLES • Handling skill "+p.Skill+"\nRoad: 8.2 speed / 100 stamina • Courser: 11 / 80 • Highlander: 9.2 / 150\nOwned horses can be selected here at no cost";
   staminaHorse.gameObject.SetActive(allowed&&gm.Hero.IsMounted);if(gm.Hero.IsMounted)staminaHorse.text=gm.Hero.Mount.SpeciesName+" • Stamina "+Mathf.RoundToInt(gm.Hero.Mount.HorseStamina);
  }
 }
 public sealed class HorseProgressionHudDriver:MonoBehaviour{[RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]static void Install(){new GameObject("Horse progression HUD").AddComponent<HorseProgressionHudDriver>();}void LateUpdate(){if(OpenWorldMobileHud.Instance)OpenWorldMobileHud.Instance.UpdateHorseProgression();}}
}
